const upgradeGlyphs={power:'M6 18L18 6M12 5l6 1 1 6M5 14l5 5',pace:'M4 8h9M4 12h13M4 16h9M16 6l4 6-4 6',health:'M12 20s-8-4.7-8-10a4 4 0 0 1 8-1 4 4 0 0 1 8 1c0 5.3-8 10-8 10z',recovery:'M12 4v16M4 12h16M7 7l2 2M17 15l2 2',reload:'M18 8a7 7 0 1 0 1 7M18 4v4h-4',mag:'M7 4h10v16H7zM9 8h6M9 12h6M9 16h6',magnet:'M6 5v8a6 6 0 0 0 12 0V5h-4v8a2 2 0 0 1-4 0V5z',stride:'M5 16l6-2 3-7 3 2-2 7 5 2v2H5z',arc:'M14 3L7 13h5l-2 8 8-11h-5z',pulse:'M12 12m-2 0a2 2 0 1 0 4 0a2 2 0 1 0-4 0M7 7a7 7 0 0 0 0 10M17 7a7 7 0 0 1 0 10',radius:'M12 3v4M12 17v4M3 12h4M17 12h4M8 8l8 8M16 8l-8 8',cooldown:'M12 5a7 7 0 1 0 7 7M12 8v4l3 2M16 4h4v4',chain:'M13 3L7 12h5l-2 9 8-11h-5zM4 8l2-2M18 17l2 2',echo:'M12 12m-3 0a3 3 0 1 0 6 0a3 3 0 1 0-6 0M4 12a8 8 0 0 1 8-8M20 12a8 8 0 0 1-8 8'};
function upgradeIcon(id){return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="'+(upgradeGlyphs[id]||upgradeGlyphs.power)+'"/></svg>'}
function upgradeRequirementsMet(item){return (!item.requiresAbility||rank('arc')||rank('pulse'))&&(!item.requires||Object.entries(item.requires).every(([id,needed])=>rank(id)>=needed))}
function evolutionHint(item){let evolution=item.evolution?item:levelUpgrades.find(candidate=>candidate.evolution&&candidate.requires&&Object.hasOwn(candidate.requires,item.id));if(!evolution)return '';let status=rank(evolution.id)>=evolution.max?'OWNED':upgradeRequirementsMet(evolution)?'READY':'IN PROGRESS',needs=Object.entries(evolution.requires).map(([id,needed])=>{let support=levelUpgrades.find(candidate=>candidate.id===id);return (support?support.name:id)+' '+Math.min(rank(id),needed)+'/'+needed}).join(' · ');return evolution.name+' / '+status+' · '+needs+(item.evolution?'':' — '+evolution.desc)}
function upgradeDescription(item){let current=rank(item.id),next=current+1,fmt=n=>String(Math.round(n*100)/100);if(current>=item.max)return 'MAX RANK · '+item.desc;if(item.id==='health')return `MAX HP ${fmt(p.maxHp)} → ${fmt(p.maxHp+20)} · HEAL UP TO 20`;if(item.id==='recovery')return `HEALTH REGEN ${fmt(.35*current)} → ${fmt(.35*next)} HP/S · 1S TICKS`;if(item.id==='reload'){let spec=weaponSpecs[p.weapon];return `${spec.name} RELOAD ${fmt(reloadSeconds(spec,current,p.perks.reload))}S → ${fmt(reloadSeconds(spec,next,p.perks.reload))}S${p.perks.reload?' · QUICK HANDS INCLUDED':''}`}if(item.id==='stride')return `MOVE ${100+5*current}% → ${100+5*next}% BASE · DASH ${fmt(5*(1-.07*current))}S → ${fmt(5*(1-.07*next))}S`;if(item.id==='magnet')return `XP PULL ${fmt(2.6*(1+.35*current))} → ${fmt(2.6*(1+.35*next))}M · SPEED ${fmt(6*(1+.15*current))} → ${fmt(6*(1+.15*next))}M/S`;if(item.id==='cooldown'){let parts=[];if(rank('arc'))parts.push(`COIL ${fmt((3.5-.5*rank('arc'))*(1-.12*current))}S → ${fmt((3.5-.5*rank('arc'))*(1-.12*next))}S`);if(rank('pulse'))parts.push(`RIPPLE ${fmt((6-.6*rank('pulse'))*(1-.12*current))}S → ${fmt((6-.6*rank('pulse'))*(1-.12*next))}S`);return parts.length?parts.join(' · '):item.desc}if(item.id==='arc'){let evolved=rank('chain')>0,targets=next+(evolved?1:0),range=(6+next)*(1+.2*rank('radius'))*(evolved?1.2:1),seconds=(3.5-.5*next)*(1-.12*rank('cooldown')),damage=1+.5*(next-1);return `AUTO SHOCK: ${targets} ${targets===1?'FOE':'FOES'} / ${fmt(range)}M / ${fmt(damage)} DMG / ${fmt(seconds)}S`}if(item.id==='pulse'){let radius=(2.8+.6*next)*(1+.2*rank('radius')),seconds=(6-.6*next)*(1-.12*rank('cooldown')),damage=1+.5*(next-1);return `AUTO PULSE + PUSH: ${fmt(damage)} DMG EACH / ${fmt(radius)}M / ${fmt(seconds)}S · MAX 6 · COVER BLOCKS`}return item.desc}
function makeLevelChoices(){let available=levelUpgrades.filter(item=>rank(item.id)<item.max&&upgradeRequirementsMet(item));if(!available.length){offeredLevels=[];levelChoices.replaceChildren();let bonus=awardPoints(progress.pending*100);progress.pending=0;pop=1.5;popEl.textContent='UPGRADES MAXED  +'+bonus;updateHUD();return false}for(let i=available.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[available[i],available[j]]=[available[j],available[i]]}let evolution=available.find(item=>item.evolution);offeredLevels=evolution?[evolution,...available.filter(item=>item!==evolution)].slice(0,3):available.slice(0,3);let thisOfferSet=offeredLevels;levelSubtitle.textContent='LEVEL '+progress.level+'  /  '+progress.pending+(progress.pending===1?' CHOICE':' CHOICES')+' REMAINING';levelChoices.replaceChildren();offeredLevels.forEach((item,index)=>{let button=document.createElement('button'),hint=evolutionHint(item);button.className='levelCard'+(item.evolution?' evolution':'');button.innerHTML='<span class="cardTop"><span class="upgradeIcon">'+upgradeIcon(item.id)+'</span><span class="levelNumber">'+(index+1)+(item.evolution?' / EVOLUTION':' / UPGRADE')+'</span></span><strong>'+item.name+'</strong><span class="upgradeDescription">'+upgradeDescription(item)+'</span>'+(hint?'<small class="evolutionHint">'+hint+'</small>':'')+'<small>RANK '+rank(item.id)+' → '+(rank(item.id)+1)+' / '+item.max+'</small>';button.addEventListener('click',event=>{if(offeredLevels===thisOfferSet&&event.detail<=1)chooseUpgrade(index)});levelChoices.appendChild(button)});return true}
// Give active tells a short readable minimum after an interrupt; no new attack
// or damage is created and already-released projectiles are left untouched.
function prepareEncounterResume(){if(waveDelay<=0&&spawnLeft>0)spawnClock=Math.max(spawnClock,.6);for(const enemy of enemies){let slot=Number.isFinite(enemy.visualId)?Math.abs(enemy.visualId)%4:0;if(enemy.windup>0)enemy.windup=Math.max(enemy.windup,.25+slot*.04);if(enemy.specialWindup>0)enemy.specialWindup=Math.max(enemy.specialWindup,.3+slot*.04)}}
function openLevelChoices(){if(state!=='playing'||p.hp<=0||progress.pending<=0)return;if(!makeLevelChoices())return;syncReloadClock();prepareEncounterResume();clearZombieImpactCues();clearShotFeedback(true);state='levelup';if(pendingReward!=='evolution')pendingReward='level';keys={};dashTime=0;flashTimer=0;flashEl.style.opacity='0';doorPrompt.style.display='none';hush();if(document.pointerLockElement===canvas)document.exitPointerLock();levelScreen.style.display='flex';levelChoices.querySelector('.levelCard')?.focus({preventScroll:true})}
function chooseUpgrade(index){if(state!=='levelup'||progress.pending<=0||p.hp<=0||document.hidden||!document.hasFocus())return;let item=offeredLevels[index];if(!item||rank(item.id)>=item.max)return;progress.ranks[item.id]=rank(item.id)+1;if(item.evolution)pendingReward='evolution';progress.pending--;if(item.id==='health'){p.maxHp+=20;p.hp=Math.min(p.maxHp,p.hp+20)}if(item.id==='arc')arcClock=.35;if(item.id==='pulse')pulseClock=.35;updateHUD();if(progress.pending>0&&makeLevelChoices()){levelChoices.querySelector('.levelCard')?.focus({preventScroll:true});return}levelScreen.style.display='none';requestPlay()}
function dropXP(enemy){if(xpGems.length>=64){let nearest=xpGems[0],best=Infinity;for(const gem of xpGems){let dx=gem.x-enemy.x,dz=gem.z-enemy.z,d=dx*dx+dz*dz;if(d<best){best=d;nearest=gem}}nearest.amount++;nearest.life=Math.max(nearest.life,30);return}xpGems.push({x:enemy.x,z:enemy.z,amount:1,life:50,phase:Math.random()*6.28})}
function collectXP(amount,quiet=false){progress.xp+=amount;let leveled=false;while(progress.xp>=progress.next){progress.xp-=progress.next;progress.level++;progress.pending++;progress.next=10+(progress.level-1)*5;leveled=true}if(leveled){if(!(typeof purchaseReceiptUntil==='number'&&gameTime<purchaseReceiptUntil)){pop=1.5;popEl.textContent='LEVEL '+String(progress.level).padStart(2,'0')}}else if(!quiet&&xpSoundClock<=0){sound('xp');xpSoundClock=.12}updateXP()}
function advanceXP(dt){xpSoundClock=Math.max(0,xpSoundClock-dt);let magnet=rank('magnet'),radius=2.6*(1+.35*magnet),speed=6*(1+.15*magnet);for(let i=xpGems.length-1;i>=0;i--){let gem=xpGems[i];gem.life-=dt;if(gem.life<=0){xpGems.splice(i,1);continue}if(gem._swept){xpGems.splice(i,1);collectXP(gem.amount);continue}let dx=p.x-gem.x,dz=p.z-gem.z,d2=dx*dx+dz*dz;if(d2>radius*radius)continue;let d=Math.sqrt(d2);if(!lineClear(gem.x,gem.z,dx,dz,d))continue;if(d<.65){xpGems.splice(i,1);collectXP(gem.amount);continue}let step=Math.min(d-.5,dt*speed);gem.x+=dx/d*step;gem.z+=dz/d*step}if(progress.pending>0)openLevelChoices()}
function maybeDrop(enemy){killsSinceDrop++;if(dropCooldown>0||killsSinceDrop<7||drops.length>=2||Math.hypot(enemy.x-p.x,enemy.z-p.z)<2.5||Math.random()>.22)return;drops.push({x:enemy.x,z:enemy.z,type:Math.random()<.5?'ammo':'double',life:22,phase:Math.random()*6.28});killsSinceDrop=0;dropCooldown=18}
function advanceArc(dt){for(let i=arcs.length-1;i>=0;i--){arcs[i].life-=dt;if(arcs[i].life<=0)arcs.splice(i,1)}let level=rank('arc');if(!level)return;arcClock-=dt;if(arcClock>0)return;let evolved=rank('chain')>0,targetCap=level+(evolved?1:0),range=(6+level)*(1+.2*rank('radius'))*(evolved?1.2:1),candidates=[];for(const enemy of enemies){if(enemy.hp<=0||enemy.breach||enemy.arrival>0)continue;let dx=enemy.x-p.x,dz=enemy.z-p.z,d2=dx*dx+dz*dz;if(d2>range*range||(candidates.length===targetCap&&d2>=candidates[candidates.length-1].d2))continue;let d=Math.sqrt(d2);if(!lineClear(p.x,p.z,dx,dz,d))continue;let index=0;while(index<candidates.length&&candidates[index].d2<d2)index++;candidates.splice(index,0,{enemy,d2});if(candidates.length>targetCap)candidates.pop()}if(!candidates.length){arcClock=.2;return}arcClock=(3.5-.5*level)*(1-.12*rank('cooldown'));let awarded=0,killed=false;arcs.length=0;for(const {enemy} of candidates){arcs.push({x:enemy.x,z:enemy.z,life:.18,bend:Math.random()*2-1,evolved});enemy.hp-=1+.5*(level-1);enemy.flash=.14;enemy.stagger=.16;enemy.hitHead=false;enemy.hitSide=1;let dead=enemy.hp<=0;impact(enemy.x,enemy.z,1.1,false,dead);powerSparks(enemy.x,enemy.z,evolved?'#e8ca88':'#a9d7c6');let points=10;if(dead){let bonus=defeatEnemy(enemy);if(bonus){points+=bonus;killed=true}}awarded+=awardPoints(points)}sound('arc');if(killed)sound('kill');if(awarded&&!(typeof purchaseReceiptUntil==='number'&&gameTime<purchaseReceiptUntil)){pop=.7;popEl.textContent='COIL  +'+awarded}updateHUD()}
function performPulse(x,z,radius,power,limit,push,echo){let candidates=[];for(const enemy of enemies){if(enemy.hp<=0||enemy.breach||enemy.arrival>0)continue;let dx=enemy.x-x,dz=enemy.z-z,d2=dx*dx+dz*dz;if(d2>radius*radius||(candidates.length===limit&&d2>=candidates[candidates.length-1].d2))continue;let d=Math.sqrt(d2);if(!lineClear(x,z,dx,dz,d))continue;let index=0;while(index<candidates.length&&candidates[index].d2<d2)index++;candidates.splice(index,0,{enemy,d2});if(candidates.length>limit)candidates.pop()}if(!candidates.length&&!echo)return false;if(pulses.length>=2)pulses.shift();pulses.push({x,z,radius,life:.42,echo});let awarded=0,killed=false;for(const {enemy,d2} of candidates){let d=Math.sqrt(d2)||1,dx=enemy.x-x,dz=enemy.z-z;enemy.hp-=power;enemy.flash=.14;enemy.stagger=.3;enemy.hitHead=false;enemy.hitSide=1;move(enemy,dx/d*push,dz/d*push,enemy.radius);let dead=enemy.hp<=0;impact(enemy.x,enemy.z,1.05,false,dead);powerSparks(enemy.x,enemy.z,echo?'#e8c58d':'#9bc7b9');let points=10;if(dead){let bonus=defeatEnemy(enemy);if(bonus){points+=bonus;killed=true}}awarded+=awardPoints(points)}sound('pulse',echo?.55:1);if(killed)sound('kill');if(awarded){if(!(typeof purchaseReceiptUntil==='number'&&gameTime<purchaseReceiptUntil)){pop=.7;popEl.textContent=(echo?'AFTERSHOCK  +':'RIPPLE  +')+awarded}updateHUD()}return true}
function advancePulse(dt){for(let i=pulses.length-1;i>=0;i--){pulses[i].life-=dt;if(pulses[i].life<=0)pulses.splice(i,1)}if(echoDelay>0){echoDelay-=dt;if(echoDelay<=0){echoDelay=0;performPulse(echoX,echoZ,echoRadius,1,4,.1,true)}}let level=rank('pulse');if(!level)return;pulseClock-=dt;if(pulseClock>0)return;let radius=(2.8+.6*level)*(1+.2*rank('radius'));if(!performPulse(p.x,p.z,radius,1+.5*(level-1),6,.22,false)){pulseClock=.2;return}pulseClock=(6-.6*level)*(1-.12*rank('cooldown'));if(rank('echo')){echoX=p.x;echoZ=p.z;echoRadius=radius*.65;echoDelay=.55}}
function advanceDrops(dt){if(state!=='playing')return;dropCooldown=Math.max(0,dropCooldown-dt);doublePoints=Math.max(0,doublePoints-dt);if(doublePoints<1e-9)doublePoints=0;for(let i=drops.length-1;i>=0;i--){let drop=drops[i];drop.life-=dt;if(drop.life<=0){drops.splice(i,1);continue}let dx=drop.x-p.x,dz=drop.z-p.z,d=Math.hypot(dx,dz);if(drop._swept||(d<1.05&&lineClear(p.x,p.z,dx,dz,d))){drops.splice(i,1);if(drop.type==='ammo'){for(const name of Object.keys(p.guns)){let gun=p.guns[name];if(gun){gun.ammo=weaponCapacity(name);gun.reserve=weaponSpecs[name].maxReserve}}cancelReload();popEl.textContent='AMMO RESUPPLIED'}else{doublePoints=25;popEl.textContent='DOUBLE POINTS  /  25s'}pop=2;sound(drop.type==='ammo'?'purchaseAmmo':'rewardPickup');updateHUD()}}let label=doublePoints>0?'2X POINTS  /  '+Math.ceil(doublePoints)+'s':'';if(pickupHud.textContent!==label)pickupHud.textContent=label}
function currentGun(){return p.guns[p.weapon]}
function reloadProgressFraction(remaining,duration){return remaining>0&&duration>0?Math.round(Math.max(0,Math.min(1,1-remaining/duration))*1e9)/1e9:0}
function updateReloadProgress(){let active=state==='playing'&&reloading>0&&reloadDuration>0;if(reloadTrack.hidden===active)reloadTrack.hidden=!active;if(!active){lastReloadPercent=-1;return}let percent=Math.min(99,Math.max(0,Math.floor(reloadProgressFraction(reloading,reloadDuration)*100)));if(percent!==lastReloadPercent){lastReloadPercent=percent;reloadFill.style.width=percent+'%';reloadTrack.setAttribute('aria-valuenow',String(percent))}}
function plannedReload(gun,capacity){return Math.min(capacity-gun.ammo,gun.reserve)}
function reloadStatus(gun,capacity,active,hasShotgun){if(active){let count=plannedReload(gun,capacity);return (gun.ammo===0?'EMPTY · ':'')+'LOADING '+count}if(gun.ammo===0)return gun.reserve===0?'OUT OF AMMO · FIND AMMO':'RELOAD NOW';if(gun.reserve===0)return 'NO RESERVE · FIND AMMO';if(gun.ammo>=capacity)return hasShotgun?'MAG FULL  ·  1 / 2 SWITCH':'MAG FULL';return hasShotgun?'R RELOAD  ·  1 / 2 SWITCH':'R TO RELOAD'}
function setHudText(node,value){let text=String(value);if(node.textContent!==text)node.textContent=text}
function updateHUD(){let gun=currentGun();setHudText($('#wave'),String(wave).padStart(2,'0'));let lowHealth=p.hp>0&&p.hp<=p.maxHp*.35,healthRatio=p.maxHp>0?Math.max(0,Math.min(1,p.hp/p.maxHp)):0;setHudText($('#hp'),Math.max(0,Math.ceil(p.hp)));setHudText($('.health small'),' HP / '+p.maxHp+(lowHealth?' · LOW':''));let hpWidth=(healthRatio*100)+'%';if($('#hpbar').style.width!==hpWidth)$('#hpbar').style.width=hpWidth;document.body.classList.toggle('critical',lowHealth);setHudText($('#score'),String(score).padStart(6,'0'));setHudText($('#kills'),kills+' KILLS');setHudText($('#ammo'),gun.ammo);setHudText($('.ammo .eyebrow'),weaponSpecs[p.weapon].name+(gun.upgraded?' / REFITTED':''));setHudText($('.ammo small'),' / '+gun.reserve+' RES');let reloadLabel=$('#reload'),reloadText=reloadStatus(gun,weaponCapacity(p.weapon),reloading>0,!!p.guns.shotgun);if(reloadLabel.textContent!==reloadText)reloadLabel.textContent=reloadText;updateReloadProgress();setHudText(perkHud,[p.perks.health?'HARDENED':null,p.perks.reload?'QUICK HANDS':null,rank('arc')?'STORM COIL '+rank('arc'):null,rank('pulse')?'RIPPLE '+rank('pulse'):null,rank('chain')?'CHAIN STORM':null,rank('echo')?'AFTERSHOCK':null].filter(Boolean).join('  /  '))}
function nextWave(){awarenessClock=0;awarenessTarget=null;spawnDeferred=false;spawnCapHeld=false;wave++;spawnLeft=Math.min(10+wave*4,45);spawnClock=wave===1?.65:.35;waveDelay=0;tailClock=0;announce=2.8;announceEl.textContent='WAVE '+String(wave).padStart(2,'0');sound('wave');updateHUD()}
// The renderer's horizontal half-frustum is currentFov regardless of aspect: the
// camera derives vertical FOV from viewport size. Use the wider hip-fire view even
// while aiming, so releasing ADS cannot reveal a freshly spawned body at the edge.
function spawnHidden(x,z){if(!spawnHiddenAtHeading(x,z,p.yaw))return false;for(const view of spawnViewHistory)if(gameTime-view.time<=.35)return spawnHiddenAtHeading(x,z,view.yaw);return true} 
