// Briefly reserve recently opened doorways against fresh offscreen spawns.
function recordOpenedDoor(door){for(const [x,z] of door.cells){recentSpawnDoors.push({x:x+.5,z:z+.5,until:gameTime+3});if(recentSpawnDoors.length>16)recentSpawnDoors.shift()}}
function spawnDoorClear(x,z){for(const door of recentSpawnDoors)if(gameTime<door.until&&(x-door.x)**2+(z-door.z)**2<2.25**2)return false;return true}
