let flankerSeen=false,flankerIntroUntil=0,bruteSeen=false,bruteIntroUntil=0,keeperSeen=false,compositionSeed=null,keeperBreathingUntil=0,stragglerNoticeUntil=0,spawnDeferred=false,spawnCapHeld=false,spawnViewHistory=[],recentSpawnDoors=[],spawnAreaRevision=-1,spawnAreaMask=0;
