function selectSpawnKind(roll,wave,seed){let brute=wave>=3?Math.min(.22,.1+(wave-3)*.015):0,flanker=wave>=2?Math.min(.3,.18+(wave-2)*.01):0;if(wave>=5&&seed!==null){let pattern=(wave+seed)%3,shift=pattern===0?.05:pattern===1?-.05:0;shift=Math.max(-brute,Math.min(flanker,shift));brute+=shift;flanker-=shift}return roll<brute?'brute':roll<brute+flanker?'flanker':'shambler'}
