function spawnAreaPotential(minRadius){if(spawnAreaRevision!==pathRevision){spawnAreaRevision=pathRevision;spawnAreaMask=0;let px=Math.floor(p.x)+.5,pz=Math.floor(p.z)+.5,margin=Math.SQRT2;for(let z=Math.max(1,Math.floor(pz-27));z<Math.min(N-1,Math.ceil(pz+27))&&spawnAreaMask!==3;z++)for(let x=Math.max(1,Math.floor(px-27));x<Math.min(N-1,Math.ceil(px+27));x++){if(pathDistance[z*N+x]<0)continue;let d=Math.hypot(x+.5-px,z+.5-pz);if(d-margin>25)continue;if(d+margin>=12)spawnAreaMask|=1;if(d+margin>=16)spawnAreaMask|=2;if(spawnAreaMask===3)break}}return !!(spawnAreaMask&(minRadius>=16?2:1))}
function spawn(preferSurge=false,forcedKind=null){if(pathCell!==Math.floor(p.z)*N+Math.floor(p.x))return false;let roll=Math.random(),kind=forcedKind||selectSpawnKind(roll,wave,compositionSeed),minRadius=kind==='flanker'?16:12,spot=null,best=-Infinity;if(kind==='brute'&&!bruteSeen&&enemies.some(e=>e.kind==='elite'))kind='shambler';if(wave<=4&&kind!=='shambler'){let specials=0;for(const enemy of enemies)if(enemy.kind==='flanker'||enemy.kind==='brute'||enemy.kind==='elite')specials++;if(specials>=2){if(forcedKind==='elite')return false;kind='shambler'}}minRadius=kind==='flanker'?16:12;if(!spawnAreaPotential(minRadius))return false;recentSpawnDoors=recentSpawnDoors.filter(door=>gameTime<door.until);spawnHistory=spawnHistory.filter(v=>gameTime-v.time<24);for(let attempt=0;attempt<48;attempt++){let angle=Math.random()*Math.PI*2,radius=minRadius+Math.random()*(25-minRadius),x=p.x+Math.sin(angle)*radius,z=p.z-Math.cos(angle)*radius,ix=Math.floor(x),iz=Math.floor(z),cell=iz*N+ix;if(ix<1||iz<1||ix>=N-1||iz>=N-1||pathDistance[cell]<0||!canMove(x,z,.5)||!spawnDoorClear(x,z)||!spawnHidden(x,z)||!enemies.every(e=>(e.x-x)**2+(e.z-z)**2>1.21))continue;let dx=x-p.x,dz=z-p.z,spread=2,last=spawnHistory[spawnHistory.length-1];if(last&&gameTime-last.time<1.2){let lx=last.x-p.x,lz=last.z-p.z,ld=Math.hypot(lx,lz);if(ld>.01&&dx*lx+dz*lz<-.5*radius*ld)continue}for(const v of spawnHistory){let hx=v.x-p.x,hz=v.z-p.z,hd=Math.hypot(hx,hz);if(hd>.01){let angular=1-(dx*hx+dz*hz)/(radius*hd),spatial=Math.min(2,Math.hypot(x-v.x,z-v.z)/10);spread=Math.min(spread,angular+spatial*.5)}}let blocked=!lineClear(p.x,p.z,dx,dz,radius),score=spread+(blocked?.45:0)-Math.min(.4,Math.max(0,pathDistance[cell]-radius*1.4)*.02)+Math.random()*.08;if(score>best){spot={x,z};best=score}}if(!spot)return false;spawnHistory.push({x:spot.x,z:spot.z,time:gameTime});if(spawnHistory.length>10)spawnHistory.shift();let base=Math.min(12,3+Math.floor((wave-1)/3)),growth=Math.min(wave*.04,.36),phase=Math.random()*7;if(compositionSeed===null)compositionSeed=Math.floor(phase*1000);
let spawned={visualId:++zombieVisualSequence,x:spot.x,z:spot.z,kind,hp:kind==='elite'?Math.min(28,base*3):kind==='brute'?Math.ceil(base*2.4):kind==='flanker'?Math.max(2,Math.ceil(base*.75)):base,phase,speed:kind==='brute'?.82+growth*.5:kind==='flanker'?1.55+growth+Math.random()*.15:kind==='elite'?1.05+growth*.5:1.05+growth+Math.random()*.25,radius:kind==='brute'?.35:kind==='flanker'?.23:.28,damage:kind==='brute'?22:kind==='flanker'?10:14,triggerRange:kind==='brute'?1.6:kind==='flanker'?1.42:1.48,reach:kind==='brute'?1.85:kind==='flanker'?1.68:1.72,windupMax:kind==='brute'?.78:kind==='flanker'?.42:.5,orbit:Math.sin(phase)<0?-1:1,attack:0,windup:0,lunge:0,specialCooldown:4,specialWindup:0,specialDx:0,specialDz:0,nav:null,blocked:false,flash:0,arrival:0,breach:null,variant:Math.random()};primeSpawnPursuit(spawned);enemies.push(spawned);if(kind==='flanker'&&!flankerSeen){flankerSeen=true;flankerIntroUntil=gameTime+5}if(kind==='brute'&&!bruteSeen){bruteSeen=true;bruteIntroUntil=gameTime+8}return true}
function killBonus(enemy){return enemy.kind==='elite'?220:enemy.kind==='brute'?150:enemy.kind==='flanker'?120:100}
// All attacks share one defeat path so a removed enemy cannot pay out twice.
function recordZombieDeath(enemy,shotgun=false,fatalHead=false){if(deathVisuals.length>=8){let incoming=(enemy.x-p.x)**2+(enemy.z-p.z)**2,settled=-1,settledScore=-Infinity,fresh=-1,freshDistance=0;for(let i=0;i<deathVisuals.length;i++){let d=deathVisuals[i],distance=(d.x-p.x)**2+(d.z-p.z)**2;if(d.age>=.65){let score=distance+16;if(incoming<score&&score>settledScore){settled=i;settledScore=score}}else if(distance>freshDistance){fresh=i;freshDistance=distance}}let chosen=settled>=0?settled:incoming<freshDistance*.64?fresh:-1;if(chosen<0)return;deathVisuals.splice(chosen,1)}deathVisuals.push({visualId:enemy.visualId,x:enemy.x,z:enemy.z,kind:enemy.kind,variant:enemy.variant,phase:enemy.phase||0,side:enemy.hitSide||1,hitHead:!!fatalHead,shotgun:!!shotgun,yaw:Math.atan2(p.x-enemy.x,p.z-enemy.z),age:0})}
function advanceZombieDeaths(dt){for(let i=deathVisuals.length-1;i>=0;i--){deathVisuals[i].age+=dt;if(deathVisuals[i].age>=.9)deathVisuals.splice(i,1)}}
function showRoleReward(kind,bonus,cache){let priority=kind==='elite'?2:1;if(roleRewardUntil>gameTime&&priority<roleRewardPriority)return;roleRewardPriority=priority;roleRewardUntil=gameTime+2.2;roleRewardEl.textContent=(kind==='elite'?'KEEPER':'BRUTE')+'  +'+(bonus*(doublePoints>0?2:1))+' BONUS'+(cache==='relocated'?' · CACHE NEAR YOU':cache==='granted'?' · CACHE +'+(doublePoints>0?800:400)+' PTS +5 XP':cache?' · CACHE':'');roleRewardEl.style.display='block'}
