function keeperCachePosition(x,z){refreshPaths();if(canMove(x,z,.25)&&objectivePathDistance(x,z)>=0)return {x,z};let best=null,bestDistance=36,ix=Math.floor(x),iz=Math.floor(z);for(let dz=-6;dz<=6;dz++)for(let dx=-6;dx<=6;dx++){let cx=ix+dx+.5,cz=iz+dz+.5,d=(cx-x)**2+(cz-z)**2;if(d>bestDistance||!canMove(cx,cz,.25)||objectivePathDistance(cx,cz)<0)continue;if(!best||d<bestDistance){best={x:cx,z:cz};bestDistance=d}}return best}
