function nearbyDoor(){let closest=null,best=1.8;for(const door of doors){if(door.open)continue;for(const [x,z] of door.cells){let dx=x+.5-p.x,dz=z+.5-p.z,d=Math.hypot(dx,dz);if(d>=best||d<.001)continue;let ray=cast(p.x,p.z,dx/d,dz/d,d);if(ray.type!==5||ray.d>d)continue;closest=door;best=d}}return closest}
