// The shared navigation field prevents bearings toward isolated objectives.
function screenDirectionArrow(forward,side){return Math.abs(side)>Math.abs(forward)?(side<0?'←':'→'):(forward<0?'↓':'↑')}
function objectivePathDistance(x,z){let ix=Math.floor(x),iz=Math.floor(z);return ix<0||iz<0||ix>=N||iz>=N?-1:pathDistance[iz*N+ix]}
// A single bearing and three coarse proximity cues keep the view readable.
function reachableGateObjective(){let target=null,best=Infinity;for(const gate of doors){if(gate.open||score<gate.price)continue;for(const [x,z] of gate.cells)for(let direction=0;direction<4;direction++){let nx=x+(direction===0?1:direction===1?-1:0),nz=z+(direction===2?1:direction===3?-1:0);if(map[nz]?.[nx]!==0)continue;let distance=objectivePathDistance(nx+.5,nz+.5);if(distance>=0&&distance<best){best=distance;target={x:nx+.5,z:nz+.5,label:'GATE: '+gate.name+' / '+gate.price+' PTS'}}}}return target}
function usefulWorkbench(){let perks=p.perks||{},gun=p.guns?.[p.weapon];return (!perks.health&&score>=perkSpecs.health.price)||(!perks.reload&&score>=perkSpecs.reload.price)||(!!gun&&!gun.upgraded&&score>=REFIT_PRICE)||(!!perks.health&&p.hp<p.maxHp&&gameTime>=fieldAidReadyAt&&score>=perkSpecs.health.aidPrice)}
