function claimCache(choice){if(state!=='playing')return;let cache=nearbyCache();if(!cache)return;let effect;if(choice==='ammo'){if(!needsReserve()){sound('purchaseDenied');return}for(const name of Object.keys(p.guns)){let gun=p.guns[name];if(gun){let limit=weaponSpecs[name].maxReserve;gun.reserve=Math.min(limit,gun.reserve+Math.ceil(limit*.35))}}effect='RESERVES RESTOCKED'}else if(choice==='heal'){if(p.hp>=p.maxHp){sound('purchaseDenied');return}let healed=Math.min(35,p.maxHp-p.hp);p.hp+=healed;effect='FIELD AID  +'+Number(healed.toFixed(1))+' HP'}else if(choice==='xp'){effect='+4 XP'}else return;cache.used=true;cache.discovered=true;awarenessClock=0;awarenessTarget=null;let gained=awardPoints(SUPPLY_BONUS);if(choice==='xp')collectXP(4,true);objectiveFeedback(effect+'  /  +'+gained+' PTS');sound(choice==='ammo'?'purchaseAmmo':'rewardPickup');updateHUD();showDoorPrompt()}
