function advanceBeacon(dt){if(!beacon.active)return;let distance=Math.hypot(p.x-beacon.x,p.z-beacon.z);if(distance>10){beacon.active=false;beaconHud.textContent='';announce=1.8;announceEl.textContent='BEACON ABANDONED';return}beacon.time=Math.max(0,beacon.time-dt);let label='BEACON  '+Math.ceil(beacon.time)+'s  /  STAY WITHIN 10M';if(beaconHud.textContent!==label)beaconHud.textContent=label;if(beacon.time<=0){beacon.active=false;beacon.used=true;beaconHud.textContent='';let gained=awardPoints(700);collectXP(6,true);announce=2.5;announceEl.textContent='BEACON SECURED  +'+gained+' / +6 XP';sound('rewardPickup');updateHUD();return}if(beacon.spawned<5){beacon.spawnClock-=dt;if(beacon.spawnClock<=0){if(enemies.length<MAX_ENEMIES&&spawn()){beacon.spawned++;beacon.spawnClock=4}else beacon.spawnClock=1}}}
