function advanceMilestone(){if(milestoneAchieved){let label='ENDLESS '+survivalTime(Math.floor(gameTime));if(goalHud.textContent!==label)goalHud.textContent=label;return}let label='SURVIVE '+survivalTime(SURVIVAL_GOAL-gameTime);if(goalHud.textContent!==label)goalHud.textContent=label;if(!finaleAnnounced&&gameTime>=SURVIVAL_GOAL-45){finaleAnnounced=true;if(!enemies.some(e=>e.kind==='elite')){nextEliteAt=Math.min(nextEliteAt,gameTime);eliteRetry=0}announce=3;announceEl.textContent='FINAL 45 SECONDS';sound('wave')}if(gameTime<SURVIVAL_GOAL||progress.pending>0||state!=='playing')return;milestoneAchieved=true;goalHud.textContent='MILESTONE CLEAR';syncReloadClock();prepareEncounterResume();clearZombieImpactCues();clearShotFeedback(true);state='milestone';keys={};dashTime=0;flashTimer=0;flashEl.style.opacity='0';doorPrompt.style.display='none';hush();if(document.pointerLockElement===canvas)document.exitPointerLock();recordRun();milestoneScreen.querySelector('.milestoneSummary').textContent=runStats();milestoneScreen.querySelector('.milestoneBuild').textContent=buildDescription()+'  |  '+lastRecordLabel;milestoneScreen.style.display='flex';milestoneScreen.querySelector('.keepGoing').focus({preventScroll:true})}
