function waveStatusLabel(){if(waveDelay>0)return wave===0?'FIRST WAVE IN '+Math.ceil(waveDelay)+'s':tailClock===-1?'MORE INCOMING '+Math.ceil(waveDelay)+'s · THREATS REMAIN':enemies.length>0?(enemies.some(e=>e.kind==='elite'&&(!Number.isFinite(e.hp)||e.hp>0))?'BREAK PAUSED · KEEPER':'BREAK PAUSED · CLEAR THREATS'):'BREAK · NEXT WAVE '+Math.ceil(waveDelay)+'s';let keeper=enemies.some(e=>e.kind==='elite'&&(!Number.isFinite(e.hp)||e.hp>0)),suffix=keeper?' · KEEPER':'';if(spawnLeft===0&&enemies.length>0&&enemies.length<=2){let known=pathCell===Math.floor(p.z)*N+Math.floor(p.x),reachable=false;if(known)for(const enemy of enemies){let x=Math.floor(enemy.x),z=Math.floor(enemy.z);if(x>=0&&z>=0&&x<N&&z<N&&pathDistance[z*N+x]>=0){reachable=true;break}}if(known&&!reachable)return enemies.length+' THREAT'+(enemies.length===1?'':'S')+' · ROUTE BLOCKED'+suffix;return (reachable?(enemies.length===1?'LAST THREAT':'REMAINING THREATS')+' · CHECK COMPASS':enemies.length+' THREAT'+(enemies.length===1?'':'S')+' REMAIN')+suffix}return (spawnLeft+enemies.length)+' REMAINING'+(spawnLeft>0&&spawnDeferred?' · INCOMING':'')+suffix}
